mapper.select:
 SELECT r.*,u.nickname,u.account_code,u.college_id,u.college_name,u.major_id,u.major_name,u.current_grade
FROM ranking r JOIN monitoring_student u ON u.user_id=r.user_id
ORDER BY r.answered_count DESC,r.active_days DESCr.duration_seconds DESC,r.answered_count DESCr.active_days DESC,r.answered_count DESC,r.user_id LIMIT #{limit} OFFSET #{offset}
